335	
336	/**
337	 * @usage To get/set on dimension, use:
338	 *  `xyVal[XY[dim]] = val;` // set on this dimension.
339	 *  `xyVal[XY[1 - dim]] = val;` // set on the perpendicular dimension.
340	 */
341	export function setDimXYValue(
342	    out: Point,
343	    dimIdx: number, // 0 | 1
344	    valueOnThisDim: MatrixXYLocator,
345	    valueOnOtherDim: MatrixXYLocator
346	): Point {
347	    out[XY[dimIdx]] = valueOnThisDim;
348	    out[XY[1 - dimIdx]] = valueOnOtherDim;
349	    return out;
350	}
351	
352	/**
353	 * Return NullUndefined if not dimension cell.
354	 */
355	function cellLayoutInfoToDimCell(
356	    cellLayoutInfo: MatrixCellLayoutInfo | NullUndefined
357	): MatrixDimensionCell | NullUndefined {
358	    return (
359	        cellLayoutInfo && (
360	            cellLayoutInfo.type === MatrixCellLayoutInfoType.leaf
361	            || cellLayoutInfo.type === MatrixCellLayoutInfoType.nonLeaf
362	        )
363	    ) ? (cellLayoutInfo as MatrixDimensionCell) : null;
364	}
365	
366	export function createNaNRectLike(): RectLike {
367	    return {x: NaN, y: NaN, width: NaN, height: NaN};
368	}
