355	            it.reset(this._cells, startIdx, startIdx + count);
356	        }
357	        else {
358	            const len = this._levels.length;
359	            // Corner locator is from `-this._levels.length` to `-1`.
360	            const startIdx = startLocator != null ? Math.max(0, startLocator + len) : 0;
361	            count = count != null ? Math.min(count, len) : len;
362	            it.reset(this._levels, startIdx, startIdx + count);
363	        }
364	        return it;
365	    }
366	
367	    resetCellIterator(
368	        it?: ListIterator<MatrixDimensionCell>
369	    ): ListIterator<MatrixDimensionCell> {
370	        return (it || new ListIterator<MatrixDimensionCell>()).reset(this._cells, 0);
371	    }
372	
373	    resetLevelIterator(
374	        it?: ListIterator<MatrixDimensionLevelInfo>
375	    ): ListIterator<MatrixDimensionLevelInfo> {
376	        return (it || new ListIterator<MatrixDimensionLevelInfo>()).reset(this._levels, 0);
377	    }
378	
379	    getLayout(outRect: RectLike, dimIdx: number, locator: MatrixXYLocator): void {
380	        const layout = this.getUnitLayoutInfo(dimIdx, locator);
381	        outRect[XY[dimIdx]] = layout ? layout.xy : NaN;
382	        outRect[WH[dimIdx]] = layout ? layout.wh : NaN;
383	    }
384	
385	    /**
386	     * Get leaf cell or get level info.
387	     * Should be able to return null/undefined if not found on x or y, thus input `dimIdx` is needed.
388	     */
389	    getUnitLayoutInfo(dimIdx: number, locator: MatrixXYLocator): MatrixCellLayoutInfo | NullUndefined {
390	        return dimIdx === this.dimIdx
391	            ? (locator < this._leavesCount ? this._cells[locator] : undefined)
392	            : this._levels[locator + this._levels.length];
393	    }
394	
395	    /**
396	     * Get dimension cell by data, including leaves and non-leaves.
397	     */
398	    getCell(value: MatrixCoordValueOption): MatrixDimensionCell | NullUndefined {
399	        const ordinal = this._scale.parse(value);
400	        return eqNaN(ordinal) ? undefined : this._cells[ordinal];
401	    }
402	
403	    /**
404	     * Get leaf count or get level count.
405	     */
406	    getLocatorCount(dimIdx: number): number {
407	        return dimIdx === this.dimIdx ? this._leavesCount : this._levels.length;
408	    }
409	
410	    getOrdinalMeta(): OrdinalMeta {
411	        return this._ordinalMeta;
412	    }
413	
414	}
415	
416	function createUniqueValueGenerator(dim: 'x' | 'y') {
417	    const dimUpper = dim.toUpperCase();
418	    const defaultValReg = new RegExp(`^${dimUpper}([0-9]+)$`);
419	    let dupBase = 0;
420	
421	    function calcDupBase(val: string | NullUndefined): void {
422	        let matchResult;
423	        if (val != null && (matchResult = val.match(defaultValReg))) {
424	            dupBase = mathMax(dupBase, +matchResult[1] + 1);
425	        }
426	    }
427	
428	    function makeUniqueValue(): string {
429	        return `${dimUpper}${dupBase++}`;
430	    }
431	
432	    // Duplicated value is allowed, because the `matrix.x/y.data` can be a tree and it's reasonable
433	    // that leaves in different subtrees has the same text. But only the first one is allowed to be
434	    // queried by the text, and the other ones can only be queried by index.
435	    // Additionally, `matrix.x/y.data: [null, null, ...]` is allowed.
436	    function ensureValueUnique(categories: (string | NullUndefined)[], cells: MatrixDimensionCell[]): void {
437	        // A simple way to deduplicate or handle illegal or not specified values to avoid unexpected behaviors.
438	        // The tree structure should not be broken even if duplicated.
439	        const cateMap = createHashMap<true, string>();
440	        for (let idx = 0; idx < categories.length; idx++) {
441	            let value = categories[idx];
442	            // value may be set to NullUndefined by users or if illegal.
443	            if (value == null || cateMap.get(value) != null) {
444	                // Still display the original option.value if duplicated, but loose the ability to query by text.
445	                categories[idx] = value = makeUniqueValue();
446	                cells[idx].option = defaults({value}, cells[idx].option);
447	            }
448	            cateMap.set(value, true);
449	        }
450	    }
451	
452	    return {calcDupBase, ensureValueUnique};
453	}
